import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem87 distingue capacidade e versao sem garantir fixacao ou rendimento',()=>{for(const [id,titulo] of [['k0fHNRurzCmYEdcHcn1V','Pistola Fixação Finca Pino Ação Direta Pregos Epi Maleta Pinador Pregador Grampeador Rebitador De Prego Pressão Ferramenta Para Drywal Gesso Concreto Aço Parede'],['k82L2iy2Q6giFdCHVbSg','Fritadeira Elétrica Air Fryer WAP Barbecue Heat WC AB1030'],['K8hXvUkqAAnbt0Om6wRj','Fritadeira Air Fryer Philco 16 Litros Paf16c Preto']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/fixação garantida|fluxo mais eficiente|sem várias rodadas|bivolt automático/i);if(id==='k82L2iy2Q6giFdCHVbSg'){assert.match(x.comentario,/6,6/);assert.match(x.comentario,/3,2/);}}});
